const news = $json.text || '';

// Escape HTML to avoid broken HTML
function escapeHtml(text) {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

// Convert Markdown links [text](url) into HTML links
function convertLinks(text) {
  return text.replace(
    /\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,
    '<a href="$2" target="_blank" style="color:#2563eb;text-decoration:none;font-weight:bold;">$1</a>'
  );
}

// Split AI response into individual news stories
const stories = news
  .split(/###\s*\d+\.\s*/)
  .filter(story => story.trim());

// Generate HTML cards
const newsCards = stories.map((story, index) => {

  let formattedStory = escapeHtml(story.trim());

  // Restore markdown links
  formattedStory = convertLinks(formattedStory);

  // Bold markdown text
  formattedStory = formattedStory.replace(
    /\*\*(.*?)\*\*/g,
    '<strong>$1</strong>'
  );

  // Convert line breaks
  formattedStory = formattedStory.replace(/\n/g, '<br>');

  return `
    <div style="
      background:#ffffff;
      border-radius:12px;
      padding:22px;
      margin-bottom:18px;
      border:1px solid #e5e7eb;
      box-shadow:0 2px 6px rgba(0,0,0,0.05);
    ">

      <div style="
        display:inline-block;
        background:#eef2ff;
        color:#4f46e5;
        padding:6px 12px;
        border-radius:20px;
        font-size:13px;
        font-weight:bold;
        margin-bottom:12px;
      ">
        AI NEWS #${index + 1}
      </div>

      <div style="
        font-size:16px;
        line-height:1.7;
        color:#374151;
      ">
        ${formattedStory}
      </div>

    </div>
  `;
}).join('');

// Final Email Dashboard
const html = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
</head>

<body style="
  margin:0;
  padding:0;
  background:#f3f4f6;
  font-family:Arial, Helvetica, sans-serif;
">

  <div style="
    max-width:800px;
    margin:0 auto;
    padding:30px 15px;
  ">

    <!-- Header -->
    <div style="
      background:linear-gradient(135deg,#111827,#312e81);
      color:white;
      padding:35px;
      border-radius:16px;
      margin-bottom:25px;
      text-align:center;
    ">

      <h1 style="
        margin:0;
        font-size:30px;
      ">
        🤖 AI News Briefing
      </h1>

      <p style="
        margin:12px 0 0;
        color:#d1d5db;
        font-size:16px;
      ">
        Today's Most Important AI Developments
      </p>

    </div>

    <!-- News Cards -->
    ${newsCards}

    <!-- Footer -->
    <div style="
      text-align:center;
      padding:25px;
      color:#6b7280;
      font-size:13px;
    ">
      Generated automatically by your AI News Agent 🤖
    </div>

  </div>

</body>
</html>
`;

return [
  {
    json: {
      html: html
    }
  }
];
